/* Live Office: one company-scoped workspace shared with the Crew app. */
(()=>{'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(c/100);
const today=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);
const plus=(d,n)=>{const x=new Date(d+'T12:00:00Z');x.setUTCDate(x.getUTCDate()+n);return x.toISOString().slice(0,10)};
let data={},busy=false,page=document.body.dataset.page||'home',query='';
const toast=t=>{$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),5000)};
const open=h=>{$('#dialog-content').innerHTML=h;$('#dialog').showModal()},close=()=>$('#dialog').close();
const memberName=id=>data.members?.find(m=>m.user_id===id)?.display_name||'Assigned crew';
const action=(command,payload)=>MM.api({action:command,payload});
const status=j=>j.cancelled_at?'cancelled':j.status.replaceAll('_',' ');
function bindForm(id,fn){$(id).onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await fn(new FormData(e.target),b.value);}catch(err){const el=e.target.querySelector('[role="status"]');if(el)el.textContent=err.message;else toast(err.message)}finally{b.disabled=false}}}
async function load(){if(MM.recovery){recover();return}if(!MM.session){auth();return}try{data=await MM.api({action:'list'});render()}catch(err){$('#main').innerHTML='<section class="card"><h1>Let’s reconnect.</h1><p id="load-error" role="alert"></p><button class="button primary" id="retry">Try again</button><button class="button" id="return-login">Back to sign in</button></section>';$('#load-error').textContent=err.message;$('#retry').onclick=load;$('#return-login').onclick=async()=>{await MM.signOut();auth()}}}
function auth(){$('#business-name').textContent='Your business, connected';$('#main').innerHTML=`<section class="auth card"><p class="eyebrow">MOW MATTER OFFICE</p><h1>Your business.<br>A little more organized.</h1><p>Customers, recurring visits and your crew’s progress in one place.</p><form id="auth" class="form"><label>Email<input name="email" type="email" required autocomplete="username"></label><label>Password<input name="password" type="password" minlength="8" required autocomplete="current-password"></label><p role="status" aria-live="polite"></p><div class="actions"><button class="button primary" value="login">Sign in</button><button class="button" value="signup">Create account</button></div></form><div class="actions auth-help"><button class="text-button" id="forgot">Forgot password?</button><button class="text-button" id="resend">Resend confirmation</button></div><p class="help">Create an account and confirm your email. Owners then create a business; crew members wait for their owner to assign their confirmed email.</p><p class="help legal-support-text"><a href="https://mowmatter.com/terms.html">Terms (review draft)</a> · <a href="https://mowmatter.com/privacy.html">Privacy</a> · <a href="https://mowmatter.com/contact.html">Support</a></p><a class="text-button" href="demo.html">Explore the sample dashboard →</a></section>`;
bindForm('#auth',async (f,kind)=>{if(kind==='signup'){await MM.signUp(f.get('email'),f.get('password'));$('#auth [role="status"]').textContent='Check your email, confirm your account, then return to sign in.'}else{await MM.signIn(f.get('email'),f.get('password'));await load()}});
$('#forgot').onclick=()=>emailHelp('recover');$('#resend').onclick=()=>emailHelp('resend');}
function emailHelp(kind){open(`<h2>${kind==='recover'?'Get back into your account.':'Confirm your email.'}</h2><form id="email-help" class="form"><label>Account email<input name="email" type="email" required autocomplete="email"></label><p role="status" aria-live="polite"></p><button class="button primary">${kind==='recover'?'Send recovery email':'Resend confirmation'}</button></form><p class="help">Check your inbox and spam folder. Email delivery is subject to your account’s authentication-email setup.</p>`);bindForm('#email-help',async f=>{if(kind==='recover')await MM.resetPassword(f.get('email'));else await MM.resend(f.get('email'));$('#email-help [role="status"]').textContent='If eligible, an email has been requested. Check your inbox.'})}
function recover(){$('#main').innerHTML='<section class="card auth"><h1>Choose a new password.</h1><form id="recovery" class="form"><label>New password<input name="password" type="password" minlength="8" required autocomplete="new-password"></label><label>Confirm password<input name="confirm" type="password" minlength="8" required autocomplete="new-password"></label><p role="status"></p><button class="button primary">Save new password</button></form></section>';bindForm('#recovery',async f=>{if(f.get('password')!==f.get('confirm'))throw Error('Passwords must match');await MM.updatePassword(f.get('password'));toast('Password updated');await load()})}
function render(){if(!data.company){$('#main').innerHTML='<section class="card auth"><p class="eyebrow">LET’S GET YOU STARTED</p><h1>Make it your business.</h1><form id="business" class="form"><label>Business name<input name="name" minlength="2" maxlength="120" required placeholder="Your lawn care company"></label><p role="status"></p><button class="button primary">Create my workspace</button></form><p class="help">Crew member? Ask your owner to assign your confirmed email, then <a href="https://crew.mowmatter.com/">open the Crew app</a>. You do not need to create a company.</p></section>';bindForm('#business',async f=>{await MM.api({action:'bootstrap',name:f.get('name')});await load()});return}
$('#business-name').textContent=data.company.name;const owner=data.profile.role==='owner';if(!owner){$('#main').innerHTML='<section class="card"><h1>Your field workspace is ready.</h1><p>Your role has access to assigned field work. Owner financials and customer contacts stay private.</p><a class="button primary" href="https://crew.mowmatter.com/">Open Crew app</a></section>';return}
const plans=data.plans||[],customers=data.customers||[],jobs=data.jobs||[],active=plans.filter(p=>p.active),recurring=active.reduce((n,p)=>n+p.price_cents*365.25/p.interval_days/12,0);
$('#business-glance').innerHTML=`<span class="eyebrow">YOUR BUSINESS, AT A GLANCE</span><strong>${money(recurring)}</strong><small>Contracted monthly equivalent</small><div class="milestone">${customers.length} customers · ${active.length} active plans</div><a href="customers.html" class="button primary full">Grow this value ↗</a><small>Build documented earnings first. A sale valuation is not calculated yet.</small>`;
if(page==='billing'){window.showMowBilling(data.company.id);return}
const titles={home:'Your business, at a glance.',customers:'Know every yard.',routes:'Keep the field moving.',financials:'Know what comes in.',team:'Office and Crew. Connected.'};
$('#main').innerHTML=`<div class="page-head"><div><p class="eyebrow">YOUR ACTUAL BUSINESS · LIVE DATA</p><h1>${titles[page]||titles.home}</h1></div><div class="actions"><button class="button" id="property-tools">Property quote</button><button class="button primary" id="new-customer">+ Customer</button></div></div>${page==='home'?dashboard(recurring,active,customers,jobs):page==='customers'?customerView(customers,plans):page==='financials'?financialView():page==='team'?teamView():routeView(jobs)}`;
$('#new-customer').onclick=()=>customerForm();$('#property-tools').onclick=()=>window.openPropertyTools();
document.querySelectorAll('[data-customer]').forEach(b=>b.onclick=()=>customerForm(customers.find(c=>c.id===b.dataset.customer)));
document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>planForm(b.dataset.plan));
document.querySelectorAll('[data-plan-action]').forEach(b=>b.onclick=()=>planAction(b.dataset.planAction,b.dataset.id));
document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>jobDetails(jobs.find(j=>j.id===b.dataset.job)));
$('#new-job')?.addEventListener('click',()=>jobForm());
$('#search')?.addEventListener('input',e=>{query=e.target.value;const q=query.toLowerCase();document.querySelectorAll('[data-search]').forEach(r=>r.hidden=!r.dataset.search.toLowerCase().includes(q))});
$('#assign')?.addEventListener('click',assign);
if(page==='financials')window.showMowAccounting(data.company.id,document.getElementById('stripe-accounting'),data.jobs||[]);
$('#cash-add')?.addEventListener('click',cashForm);
if($('#message'))bindForm('#message',async f=>{await MM.api({action:'message',text:f.get('text')});await load();toast('Team message saved')});
$('#export')?.addEventListener('click',exportCustomers);}
function dashboard(recurring,active,customers,jobs){const live=jobs.filter(j=>!j.cancelled_at),day=live.filter(j=>j.service_date===today()),done=day.filter(j=>j.status==='completed'),next=live.filter(j=>j.service_date>=today()&&j.status!=='completed').slice(0,6);return `<div class="stats kpis"><div><small>Recurring monthly equivalent</small><strong>${money(recurring)}</strong><span>Scheduled rate × annual visits ÷ 12</span></div><div><small>Customer relationships</small><strong>${customers.length}</strong><span>${active.length} active service plans</span></div><div><small>Today’s progress</small><strong>${done.length} / ${day.length}</strong><span>Visits complete</span></div><div><small>Your team</small><strong>${data.members.length}</strong><span>Connected accounts</span></div></div><div class="split"><section class="card"><div class="section-head"><h2>Next on the route</h2><a href="routes.html">All visits →</a></div>${jobList(next)}<a class="button" href="customers.html">Set up recurring work</a></section><section class="card onboarding"><p class="eyebrow">BUILD A BUSINESS THAT LASTS</p><h2>Your next chapter starts here.</h2><ul class="steps"><li>${customers.length?'✓':'1'} Save your first customer</li><li>${active.length?'✓':'2'} Set a recurring service plan</li><li>${data.members.length>1?'✓':'3'} Connect your crew</li><li>${jobs.some(j=>j.status==='completed')?'✓':'4'} Complete a visit with proof</li></ul><a class="button primary full" href="customers.html">Grow my recurring route</a><p class="help">Revenue is a contract projection, not collected cash. SMS is not enabled. Set up payment collection from Billing.</p></section></div><section class="card"><h2>What’s happening in the field</h2>${data.events.slice(0,8).map(e=>`<div class="message"><b>${esc(e.action.replaceAll('_',' '))}</b> · ${esc(jobs.find(j=>j.id===e.job_id)?.address||'Visit')}<small>${esc(new Date(e.created_at).toLocaleString())}</small></div>`).join('')||'<p class="empty">Crew activity appears here when your first real job starts.</p>'}</section>`}
function jobList(jobs){return `<ul class="job-list">${jobs.map(j=>`<li data-search="${esc(j.address+' '+j.customer_name)}"><div style="flex:1"><b>${esc(j.address)}</b><small>${esc(j.customer_name)} · ${esc(j.service_date)} · ${esc(j.scheduled_time.slice(0,5))}<br>${esc(memberName(j.assigned_to))}</small></div><span class="pill ${j.cancelled_at?'cancelled':esc(j.status)}">${esc(status(j))}</span><button class="button" data-job="${j.id}">Details</button></li>`).join('')||'<li class="empty">No visits here yet. Start with a customer and a service plan.</li>'}</ul>`}
function routeView(jobs){return `<section class="card"><div class="section-head"><h2>Scheduled visits</h2><button class="button primary" id="new-job">+ One-time visit</button></div><label class="form">Find a visit<input id="search" type="search" value="${esc(query)}" placeholder="Customer or address"></label><p class="help">Visits are listed by date and time. Navigation opens your map app; AI route optimization is still in development. Up to 500 visits are shown.</p>${jobList(jobs)}</section>`}
function customerView(customers,plans){return `<section class="card"><div class="section-head"><h2>Your customer book</h2><button class="button" id="export">Export CSV</button></div><label class="form">Find a customer<input id="search" type="search" value="${esc(query)}" placeholder="Name or address"></label><div class="customer-grid">${customers.map(c=>{const ps=plans.filter(p=>p.customer_id===c.id);return `<article class="customer-card" data-search="${esc(c.name+' '+c.address)}"><div class="section-head"><h3>${esc(c.name)}</h3><button class="text-button" data-customer="${c.id}">Edit</button></div><p>${esc(c.address)}<br><span class="help">${esc(c.city)}</span></p><small>${esc(c.email)} ${esc(c.phone)}</small>${ps.map(p=>`<div class="plan-row"><b>${money(p.price_cents)} / visit</b><small>Every ${p.interval_days} days · ${esc(memberName(p.assigned_to))} · ${p.active?'Active':'Paused'}</small><div class="actions"><button class="text-button" data-plan-action="${p.active?'pause_plan':'resume_plan'}" data-id="${p.id}">${p.active?'Pause':'Resume'}</button>${p.active?`<button class="text-button" data-plan-action="generate_plan" data-id="${p.id}">Extend schedule</button>`:''}</div></div>`).join('')}<button class="button full" data-plan="${c.id}">+ Recurring service</button></article>`}).join('')||'<p class="empty">Your customer book starts with one yard. Add a customer to set up recurring visits.</p>'}</div></section>`}
const field=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const services=()=>`<fieldset class="checklist"><legend>Services</legend>${['Mow','Edge','Trim','Blow','Cleanup'].map(s=>`<label><input name="services" value="${s}" type="checkbox" ${['Mow','Edge','Blow'].includes(s)?'checked':''}>${s}</label>`).join('')}</fieldset>`;
const crewSelect=value=>`<label>Assigned crew<select name="assigned_to">${data.members.map(m=>`<option value="${m.user_id}" ${m.user_id===value?'selected':''}>${esc(m.display_name)}</option>`).join('')}</select></label>`;
function customerForm(c={}){const id=c.id||crypto.randomUUID();open(`<h2>${c.id?'Update this relationship.':'Add the next yard.'}</h2><form id="customer-form" class="form">${field('Customer name','name',c.name,'text','required maxlength="100"')}${field('Property address','address',c.address,'text','required minlength="3" maxlength="200"')}${field('City and state','city',c.city||'Palm Coast, FL','text','required maxlength="100"')}${field('Email','email',c.email,'email','maxlength="254"')}${field('Phone','phone',c.phone,'tel','maxlength="30"')}<label>Access and service notes<textarea name="notes" maxlength="1500">${esc(c.notes)}</textarea></label><div class="two-fields">${field('Latitude (optional)','latitude',c.latitude??'','number','step="any" min="-90" max="90"')}${field('Longitude (optional)','longitude',c.longitude??'','number','step="any" min="-180" max="180"')}</div><label class="check"><input name="notification_consent" type="checkbox" ${c.notification_consent?'checked':''}>Customer agreed to service updates</label><p class="help">SMS is disabled. Customer changes apply to newly generated visits; existing visits retain their saved details.</p><p role="status"></p><button class="button primary full">Save customer</button></form>`);bindForm('#customer-form',async f=>{await action('save_customer',{id,...Object.fromEntries(f),notification_consent:f.has('notification_consent')});close();await load();toast('Customer saved')})}
function planForm(customer_id){const id=crypto.randomUUID();open(`<h2>Turn visits into recurring work.</h2><p>${esc(data.customers.find(c=>c.id===customer_id)?.name)}</p><form id="plan-form" class="form">${crewSelect()}${field('First visit','first_date',today(),'date',`required min="${today()}"`)}${field('Start time','scheduled_time','09:00','time','required')}<label>Frequency<select name="interval_days"><option value="7">Every week</option><option value="14" selected>Every two weeks</option><option value="28">Every four weeks</option></select></label>${field('Price per visit ($)','price','45','number','required min="0" max="100000" step=".01"')}${services()}<label class="check"><input name="requires_photo" type="checkbox" checked>Require completion photo</label><p class="help">Creates the first 60 days of visits. Extend the schedule as needed. This saves a service plan; it does not charge a card or create a signed customer contract.</p><p role="status"></p><button class="button primary full">Save plan & schedule visits</button></form>`);bindForm('#plan-form',async f=>{await action('create_plan',{id,customer_id,...Object.fromEntries(f),price_cents:Math.round(Number(f.get('price'))*100),services:f.getAll('services'),requires_photo:f.has('requires_photo')});close();await load();toast('Recurring plan and visits saved')})}
function planAction(command,id){const text=command==='pause_plan'?'Pause this service plan? Upcoming scheduled visits will be cancelled. Work already underway stays active.':command==='resume_plan'?'Resume this plan? Future visits paused with this plan will be restored. Manually cancelled visits stay cancelled.':'Extend this plan through '+plus(today(),90)+'? Existing recurring visits will not be duplicated.';open(`<h2>${command==='pause_plan'?'Pause recurring work.':command==='resume_plan'?'Resume recurring work.':'Keep your schedule ahead.'}</h2><p>${text}</p><form id="plan-action" class="form"><p role="status"></p><button class="button primary">Confirm</button></form>`);bindForm('#plan-action',async()=>{const r=await action(command,{id,through:plus(today(),90)});close();await load();toast(r.generated===undefined?'Plan updated':r.generated+' new visits scheduled')})}
function jobForm(j){const edit=!!j,customers=data.customers||[];if(!edit&&!customers.length){toast('Add a customer first');return}const id=j?.id||crypto.randomUUID();open(`<h2>${edit?'Adjust this visit.':'Schedule a one-time visit.'}</h2><form id="job-form" class="form">${edit?'':`<label>Customer<select name="customer_id">${customers.map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.address)}</option>`).join('')}</select></label>`}${crewSelect(j?.assigned_to)}${field('Service date','service_date',j?.service_date||today(),'date',`required min="${today()}"`)}${field('Start time','scheduled_time',j?.scheduled_time?.slice(0,5)||'09:00','time','required')}${edit?'':field('Price per visit ($)','price','45','number','required min="0" max="100000" step=".01"')+services()}<label>Visit notes<textarea name="notes" maxlength="1500">${esc(j?.notes||'')}</textarea></label><p role="status"></p><button class="button primary full">Save visit</button></form>`);bindForm('#job-form',async f=>{const v=Object.fromEntries(f);if(edit)await action('edit_job',{id,...v});else{const c=customers.find(x=>x.id===v.customer_id);await MM.api({action:'create_job',job:{id,...v,customer_name:c.name,address:c.address,city:c.city,customer_email:c.email,customer_phone:c.phone,latitude:c.latitude,longitude:c.longitude,notification_consent:c.notification_consent,notes:v.notes||c.notes,services:f.getAll('services'),requires_photo:true,price_cents:Math.round(Number(f.get('price'))*100)}})}close();await load();toast('Visit saved. Crew receives the change on refresh.')})}
function jobDetails(j){open(`<h2>${esc(j.address)}</h2><p>${esc(j.customer_name)} · ${esc(status(j))} · ${money(j.price_cents||0)}</p><p>${esc(j.notes)}</p>${j.cancelled_at?`<p class="notice">Cancelled: ${esc(j.cancellation_reason)}</p>`:''}${!j.cancelled_at&&['scheduled','blocked'].includes(j.status)?'<div class="actions"><button id="edit-visit" class="button">Reschedule / reassign</button><button id="cancel-visit" class="button danger">Cancel visit</button></div>':''}<h3>Job timeline</h3><ul class="timeline">${data.events.filter(e=>e.job_id===j.id).map(e=>`<li>${esc(e.action.replaceAll('_',' '))}<small>${esc(new Date(e.created_at).toLocaleString())}</small>${e.payload.manual?`<small>Manual: ${esc(e.payload.manual_reason)}</small>`:''}</li>`).join('')||'<li>No field activity yet.</li>'}</ul><div class="photo-grid">${data.photos.filter(p=>p.job_id===j.id).map(p=>`<a href="${esc(p.url)}" target="_blank" rel="noopener"><img src="${esc(p.url)}" alt="Private job completion photo"></a>`).join('')}</div><h3>Homeowner updates</h3>${data.notifications.filter(n=>n.job_id===j.id).map(n=>`<div class="message">${esc(n.body)}<small>${esc(({sent:'Email accepted by Resend',failed:'Email failed · Retry available',pending_provider:'Email provider not connected · Not sent',held_no_consent:'Not sent · Consent required',held_no_contact:'Not sent · Email required'})[n.status]||n.status)}</small>${['failed','pending_provider'].includes(n.status)&&Date.now()-Date.parse(n.created_at)<23*3600000?`<button class="button" data-email-retry="${esc(n.event_id)}" data-email-job="${esc(j.id)}">Retry email</button>`:''}</div>`).join('')||'<p class="help">Start and Complete create customer email updates when consent and an email address are present. SMS is disabled.</p>'}`);
$('#edit-visit')?.addEventListener('click',()=>jobForm(j));$('#cancel-visit')?.addEventListener('click',()=>{open('<h2>Cancel this visit.</h2><form id="cancel-form" class="form"><label>Reason<input name="reason" minlength="3" maxlength="300" required></label><p class="help">The visit stays in your history and is removed from the active Crew route.</p><p role="status"></p><button class="button primary">Confirm cancellation</button></form>');bindForm('#cancel-form',async f=>{await action('cancel_job',{id:j.id,reason:f.get('reason')});close();await load()})})}
function financialView(){const cash=data.cash||[],month=today().slice(0,7),entries=cash.filter(e=>e.entry_date.startsWith(month)),income=entries.filter(e=>e.kind==='income').reduce((n,e)=>n+e.amount_cents,0),cost=entries.filter(e=>e.kind==='expense').reduce((n,e)=>n+e.amount_cents,0);return `<section class="card" id="stripe-accounting"><h2>Customer payments & payouts</h2><p role="status">Loading payment account…</p></section><div class="stats"><div><small>Recorded income this month</small><strong>${money(income)}</strong></div><div><small>Recorded expenses this month</small><strong>${money(cost)}</strong></div><div><small>Recorded cash difference</small><strong>${money(income-cost)}</strong></div></div><section class="card"><div class="section-head"><h2>Your cash record</h2><button class="button primary" id="cash-add">+ Record income / expense</button></div><p class="help">Manual records only. This is not bank reconciliation, an invoice ledger or accounting profit. Customer payments and subscription billing appear separately above.</p><ul class="job-list">${cash.map(e=>`<li><div style="flex:1"><b>${esc(e.note)}</b><small>${esc(e.entry_date)} · ${esc(e.kind)}</small></div><strong>${e.kind==='expense'?'−':''}${money(e.amount_cents)}</strong></li>`).join('')||'<li class="empty">Record collected revenue and costs to start documenting your business.</li>'}</ul></section>`}
function cashForm(){const id=crypto.randomUUID();open(`<h2>Document the numbers.</h2><form id="cash-form" class="form"><label>Type<select name="kind"><option value="income">Collected income</option><option value="expense">Paid expense</option></select></label>${field('Amount ($)','amount','','number','required min=".01" max="100000" step=".01"')}${field('Date','entry_date',today(),'date','required')}${field('Description','note','','text','required maxlength="300"')}<p class="help">This is a manual record. No money moves and no payment is processed.</p><p role="status"></p><button class="button primary full">Save record</button></form>`);bindForm('#cash-form',async f=>{await action('cash_entry',{id,...Object.fromEntries(f),amount_cents:Math.round(Number(f.get('amount'))*100)});close();await load()})}
function teamView(){return `<div class="split"><section class="card"><h2>Your crew</h2>${data.members.map(m=>`<p><b>${esc(m.display_name)}</b> <span class="pill">${esc(m.role)}</span></p>`).join('')}<button class="button primary" id="assign">Connect confirmed crew account</button><p class="help">Crew members create and confirm their accounts first. Assign their email to grant access to this business and their assigned jobs.</p><a href="https://crew.mowmatter.com/" class="button">Open Crew app ↗</a></section><section class="card"><h2>Team messages</h2>${data.messages.slice().reverse().map(m=>`<div class="message"><small>${esc(memberName(m.actor_id))} · ${esc(new Date(m.created_at).toLocaleString())}</small>${esc(m.body)}</div>`).join('')||'<p>No team messages yet.</p>'}<form id="message" class="form"><label>Message<textarea name="text" required maxlength="2000"></textarea></label><p role="status"></p><button class="button primary">Send team message</button></form></section></div>`}
function assign(){open('<h2>Connect a crew account.</h2><form id="assign-form" class="form"><label>Confirmed account email<input name="email" type="email" required></label><label>Crew display name<input name="name" maxlength="80" required></label><p role="status"></p><button class="button primary">Connect crew member</button></form>');bindForm('#assign-form',async f=>{await MM.api({action:'assign_member',...Object.fromEntries(f)});close();await load()})}
function exportCustomers(){const rows=[['Name','Address','City','Email','Phone'],...data.customers.map(c=>[c.name,c.address,c.city,c.email,c.phone])],csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@\-]/,"'").replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='mowmatter-customers.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#close-dialog').onclick=close;$('#refresh').onclick=async()=>{const b=$('#refresh');b.disabled=true;b.setAttribute('aria-busy','true');try{await load()}finally{b.disabled=false;b.removeAttribute('aria-busy')}};$('#logout').onclick=async()=>{await MM.signOut();$('#business-glance').replaceChildren();auth()};
const mobileNav=$('#mobile-nav-dialog'),nav=$('#office-nav'),menu=$('#mobile-menu'),navHome=nav.parentElement;
function closeNavigation(){if(mobileNav.open)mobileNav.close()}
mobileNav.addEventListener('close',()=>{navHome.prepend(nav);document.body.classList.remove('nav-open');menu.setAttribute('aria-expanded','false');menu.focus()});
menu.onclick=()=>{if(mobileNav.open){closeNavigation();return}mobileNav.append(nav);document.body.classList.add('nav-open');menu.setAttribute('aria-expanded','true');mobileNav.showModal();$('#close-mobile-nav').focus()};
$('#close-mobile-nav').onclick=closeNavigation;
mobileNav.addEventListener('click',e=>{if(e.target===mobileNav)closeNavigation();if(e.target.closest('nav a, #logout'))closeNavigation()});
window.matchMedia?.('(min-width:769px)').addEventListener('change',e=>{if(e.matches)closeNavigation()});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-email-retry]');if(!b||b.disabled)return;b.disabled=true;try{const r=await MM.api({action:'retry_email',job_id:b.dataset.emailJob,event_id:b.dataset.emailRetry});close();await load();toast(r.notification_status==='sent'?'Email accepted by Resend.':'Email not sent: '+String(r.notification_status||'No eligible update').replaceAll('_',' '));}catch(err){toast(err.message)}finally{b.disabled=false}});
MM.ready.then(load);setInterval(()=>{if(page!=='billing'&&page!=='financials'&&MM.session&&!MM.recovery&&!document.hidden&&!$('#dialog').open&&!mobileNav.open&&!$('#main input:focus')&&!$('#message textarea')?.value&&!busy){busy=true;load().finally(()=>busy=false)}},30000);
})();
